const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sakha Republic geometry (approximate bounding box)
  // Sakha Republic (Yakutia): ~62°N to 73°N, ~105°E to 142°E
  const sakhaRepublic = ee.Geometry.Rectangle([105, 62, 142, 73]);

  // 2. Load MODIS Active Fire data
  // MOD14A1 is the Terra satellite active fire product (1km resolution, daily)
  const fireCollection = ee.ImageCollection('MODIS/006/MOD14A1')
    .filterDate('2020-08-06', '2020-08-07')
    .filterBounds(sakhaRepublic);

  const collectionSize = await fireCollection.size().getInfo();
  console.log(`MODIS MOD14A1 images on 2020-08-06: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No MODIS data available for this date.');
    console.log('C1');
    return;
  }

  // 3. Process the fire data
  // MOD14A1 has band 'FireMask' where values indicate fire confidence
  // Fire mask values: 0=no fire, 1=low confidence, 2=medium, 3=high
  // We count pixels with FireMask >= 1 (any fire detection)

  const fireImage = fireCollection.first();

  // Count all fire detections (FireMask > 0)
  const fireCount = fireImage
    .select('FireMask')
    .gt(0)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: sakhaRepublic,
      scale: 1000,
      maxPixels: 1e9
    })
    .get('FireMask')
    .getInfo();

  console.log(`Fire detections (FireMask > 0): ${fireCount}`);

  // 4. Also get a count of high confidence fires (FireMask == 3)
  const highConfidenceCount = fireImage
    .select('FireMask')
    .eq(3)
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: sakhaRepublic,
      scale: 1000,
      maxPixels: 1e9
    })
    .get('FireMask')
    .getInfo();

  console.log(`High confidence fires (FireMask == 3): ${highConfidenceCount}`);

  // 5. Validation and answer
  if (fireCount === null || fireCount === undefined) {
    console.log('Fire count is null.');
    console.log('C3');
    return;
  }

  if (fireCount === 0) {
    console.log('No active fires detected.');
    console.log('B');
    return;
  }

  // Check if more than 8 fires
  if (fireCount > 8) {
    console.log(`Total fires: ${fireCount} (> 8)`);
    console.log('A');
  } else {
    console.log(`Total fires: ${fireCount} (<= 8)`);
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
